  function showToast(message, tone=''){
    const root=$('#toast-root'); if(!root)return; root.innerHTML=`<div class="toast ${tone}">${esc(message)}</div>`;
    clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',3000);
  }
  function setStatus(text,online=false){const el=$('#storage-status');if(el){el.innerHTML=`<i style="background:${online?'#95c6a7':'#d4b77b'}"></i>${esc(text)}`}}
  function currencyIcon(type){return type==='crystals'?'✧':type==='seasonal_tokens'?'✿':'✦'}
  function currencyLabel(type){return type==='crystals'?'kristal':type==='seasonal_tokens'?'mevsim pulu':'yıldız'}
  function currencyBalance(type){return type==='crystals'?state.crystals:type==='seasonal_tokens'?Number(state.seasonalTokens)||0:state.stars}
