  function gameDay(){return new Date().toLocaleDateString('en-CA')}
  function gameTodayComplete(key){return state.gameDaily?.[key]===gameDay()}
  function playGameSound(kind='tap'){if(!state.gameSound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const context=new Audio(),osc=context.createOscillator(),gain=context.createGain(),tones={tap:440,match:660,win:880,miss:220,open:520};osc.type='sine';osc.frequency.value=tones[kind]||440;gain.gain.setValueAtTime(.045,context.currentTime);gain.gain.exponentialRampToValueAtTime(.001,context.currentTime+.16);osc.connect(gain);gain.connect(context.destination);osc.start();osc.stop(context.currentTime+.17);osc.onended=()=>context.close()}catch{}}
